def is_prime_number(n):
    if n <= 1:
        return False
    for i in range(2, n):
        if n % i == 0:
            return False
    return True

def is_prime(L):
    L2 = []
    for x in L:
        L2.append(is_prime_number(x))
    return L2

def count_freq(s, L):
    counts = []
    for x in L:
        counts.append(s.count(x))
    return counts
